cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Begin transaction
const transaction = db.transaction(() => {
  // 1. Update TrailFlex Joggers: item 9716794911 -> 2364909101 (Olive, M, \$53.89)
  db.prepare(\"UPDATE order_items SET item_id = ?, options = ?, unit_price = ? WHERE order_id = ? AND item_id = ?\")
    .run('2364909101', JSON.stringify({color: 'Olive', size: 'M'}), 53.89, '#W4705780', '9716794911');

  // 2. Update Everyday Crew Tee: item 5610875649 -> 7389318502 (Black, L, \$23.91)
  db.prepare(\"UPDATE order_items SET item_id = ?, options = ?, unit_price = ? WHERE order_id = ? AND item_id = ?\")
    .run('7389318502', JSON.stringify({color: 'Black', size: 'L'}), 23.91, '#W4705780', '5610875649');

  // 3. Add payment record for the price difference (+\$3.17)
  db.prepare(\"INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)\")
    .run('#W4705780', 'payment', 3.17, 'paypal_5098475');

  // 4. Update order status to 'pending (item modified)'
  db.prepare(\"UPDATE orders SET status = ? WHERE order_id = ?\")
    .run('pending (item modified)', '#W4705780');
});

transaction();

// Verify the changes
const order = db.prepare(\"SELECT order_id, status FROM orders WHERE order_id = '#W4705780'\").get();
const items = db.prepare(\"SELECT item_id, name, unit_price, options FROM order_items WHERE order_id = '#W4705780'\").all();
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = '#W4705780'\").all();

console.log('=== UPDATED ORDER ===');
console.log(JSON.stringify(order, null, 2));
console.log('=== UPDATED ITEMS ===');
console.log(JSON.stringify(items, null, 2));
console.log('=== PAYMENT HISTORY ===');
console.log(JSON.stringify(payments, null, 2));
"

